<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Kart Racing Results</title>
    <style>
        :root {
            --gold: #FFD700;
            --gold-dark: #F5A623;
            --silver: #C0C0C0;
            --bronze: #CD7F32;
            --bg-dark: rgba(0, 0, 0, 0.75);
            --text-white: #ffffff;
            --text-gray: #a0a0a0;
            --font-main: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            --font-mono: 'Courier New', Courier, monospace;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            user-select: none; /* Prevent selection for app-like feel */
        }

        body {
            font-family: var(--font-main);
            background-color: #1a1a1a;
            color: var(--text-white);
            height: 100vh;
            width: 100vw;
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
            /* Simulating the blurred background game scene */
            background-image: url('https://images.unsplash.com/photo-1511882150382-421056c89033?q=80&w=2070&auto=format&fit=crop'); 
            background-size: cover;
            background-position: center;
        }

        /* Overlay to darken the background image */
        body::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.7); /* Darken overlay */
            backdrop-filter: blur(8px);
            z-index: -1;
        }

        .container {
            width: 900px;
            max-width: 95%;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
            position: relative;
        }

        /* --- HEADER / PODIUM SECTION --- */
        .header-section {
            text-align: center;
            margin-bottom: 10px;
        }

        h1 {
            font-size: 3rem;
            text-transform: uppercase;
            letter-spacing: 2px;
            text-shadow: 0 4px 10px rgba(0,0,0,0.5);
            margin-bottom: 25px;
            font-weight: 800;
        }

        .podium-container {
            display: flex;
            justify-content: center;
            align-items: flex-end;
            gap: 15px;
            height: 220px;
            margin-bottom: 10px;
            padding: 0 20px;
        }

        .podium-step {
            display: flex;
            flex-direction: column;
            align-items: center;
            position: relative;
            transition: transform 0.3s ease;
        }

        .podium-step:hover {
            transform: translateY(-5px);
        }

        /* Avatar Styling */
        .avatar-wrapper {
            position: relative;
            z-index: 2;
            margin-bottom: -15px; /* Overlap the box slightly */
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .medal-icon {
            font-size: 24px;
            margin-bottom: 5px;
            filter: drop-shadow(0 2px 4px rgba(0,0,0,0.5));
        }

        .avatar {
            width: 60px;
            height: 60px;
            border-radius: 50%;
            border: 3px solid white;
            object-fit: cover;
            background-color: #333;
            box-shadow: 0 4px 8px rgba(0,0,0,0.4);
        }

        .racer-name-podium {
            font-size: 0.9rem;
            font-weight: bold;
            margin-top: 5px;
            text-shadow: 0 1px 3px black;
            white-space: nowrap;
            max-width: 90px;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        /* The Box/Step */
        .step-box {
            width: 110px;
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
            align-items: center;
            padding-bottom: 15px;
            border-radius: 12px 12px 4px 4px;
            box-shadow: 0 10px 20px rgba(0,0,0,0.3);
            position: relative;
            overflow: hidden;
        }

        .step-rank {
            font-size: 2.5rem;
            font-weight: 800;
            opacity: 0.9;
        }

        /* Specific Podium Colors */
        .step-1 { 
            height: 140px; 
            background: linear-gradient(to bottom, #ffd700, #ffaa00);
            z-index: 3;
            order: 2; /* Center */
        }
        .step-2 { 
            height: 100px; 
            background: linear-gradient(to bottom, #e0e0e0, #b0b0b0);
            order: 1; /* Left */
        }
        .step-3 { 
            height: 80px; 
            background: linear-gradient(to bottom, #cd7f32, #a0522d);
            order: 3; /* Right */
        }


        /* --- RESULTS TABLE --- */
        .results-table-container {
            width: 100%;
            background: rgba(20, 20, 20, 0.85);
            border-radius: 12px;
            padding: 15px 0;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
            border: 1px solid rgba(255,255,255,0.1);
            max-height: 400px;
            overflow-y: auto;
            /* Custom Scrollbar */
            scrollbar-width: thin;
            scrollbar-color: #555 #222;
        }

        .results-table-container::-webkit-scrollbar {
            width: 8px;
        }
        .results-table-container::-webkit-scrollbar-track {
            background: #222; 
        }
        .results-table-container::-webkit-scrollbar-thumb {
            background: #555; 
            border-radius: 4px;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            font-size: 0.95rem;
        }

        th {
            text-align: left;
            padding: 10px 20px;
            color: #888;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            border-bottom: 1px solid #333;
        }

        td {
            padding: 12px 20px;
            border-bottom: 1px solid rgba(255,255,255,0.05);
            vertical-align: middle;
        }

        tr:last-child td {
            border-bottom: none;
        }

        tr:hover {
            background-color: rgba(255,255,255,0.05);
        }

        .col-rank { width: 50px; color: #888; font-family: var(--font-mono); }
        .col-racer { 
            display: flex; 
            align-items: center; 
            gap: 12px; 
            font-weight: 600;
            color: #fff;
        }
        .col-time { font-family: var(--font-mono); color: #ddd; text-align: right; }
        .col-points { font-family: var(--font-mono); font-weight: bold; text-align: right; width: 60px;}

        .dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            display: inline-block;
            box-shadow: 0 0 5px rgba(0,0,0,0.3);
        }

        /* --- FOOTER --- */
        .footer-section {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 15px;
            width: 100%;
            margin-top: 10px;
        }

        .hint-text {
            color: #888;
            font-size: 0.9rem;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .actions {
            display: flex;
            gap: 20px;
        }

        .btn {
            padding: 14px 40px;
            border-radius: 30px;
            border: none;
            font-size: 1.1rem;
            font-weight: 800;
            cursor: pointer;
            text-transform: uppercase;
            transition: all 0.2s ease;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .btn-primary {
            background: linear-gradient(to right, #FFD700, #FFA500);
            color: #000;
            box-shadow: 0 4px 15px rgba(255, 165, 0, 0.4);
        }

        .btn-primary:hover {
            transform: scale(1.05);
            box-shadow: 0 6px 20px rgba(255, 165, 0, 0.6);
        }

        .btn-secondary {
            background: rgba(255,255,255,0.1);
            color: #fff;
            border: 1px solid rgba(255,255,255,0.2);
        }

        .btn-secondary:hover {
            background: rgba(255,255,255,0.2);
        }

        /* Responsive adjustments */
        @media (max-width: 768px) {
            h1 { font-size: 2rem; }
            .podium-container { transform: scale(0.9); }
            .col-time, .col-lap { display: none; } /* Hide less critical cols on mobile */
            .container { width: 100%; padding: 10px; }
        }
    </style>
</head>
